      pricePerCertAmount: z.number().int().nonnegative().optional(),
      savings: z.number().optional(),
      popular: z.boolean().optional(),
      features: z.array(z.string()).optional(),
      // KS-440: `currency` is present only on the single-bundle response
      // (GET /bundles/{id}); list items omit it — it sits at the list envelope's
      // top level. Optional so both responses validate.
      currency: z.string().optional(),
